"""jacobian_symbolic.py

Symbolically differentiated state Jacobian of the scaled model, generated with sympy and
checked against a central-difference Jacobian to 1e-9.  Valid on the temperature branch
Topt1 < T < Topt2, where the cold type is on its supra-optimal side and the warm type on its
sub-optimal side.  Used by the variational integration in periodic_continuation.py, where a
finite-difference Jacobian would dominate the cost.
"""
import numpy as np


def jac(N, P1, P2, Z, D, T, I0):
    return np.array([
        [1.1*N*P1*np.exp(-(0.25*T - 3.75)**2)/(N + 1.2)**2 + 1.1*N*P2*np.exp(-(0.142857142857143*T - 3.57142857142857)**2)/(N + 0.5)**2 - 1.1*P1*np.exp(-(0.25*T - 3.75)**2)/(N + 1.2) - 1.1*P2*np.exp(-(0.142857142857143*T - 3.57142857142857)**2)/(N + 0.5) - 0.12, -1.1*N*np.exp(-(0.25*T - 3.75)**2)/(N + 1.2), -1.1*N*np.exp(-(0.142857142857143*T - 3.57142857142857)**2)/(N + 0.5), 0, 0.05*2.0**((1/10)*T - 2.0)],
        [-1.1*N*P1*np.exp(-(0.25*T - 3.75)**2)/(N + 1.2)**2 + 1.1*P1*np.exp(-(0.25*T - 3.75)**2)/(N + 1.2), 1.1*N*np.exp(-(0.25*T - 3.75)**2)/(N + 1.2) - 1.2*P1**2.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)) + 0.4*P1**3.0*Z/((P1 + 1.0)**2*(P1**2.0 + P2**2.0)) + 0.8*P1**4.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)**2) - 0.1, 0.8*P1**3.0*P2**1.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)**2), -0.4*P1**3.0/((P1 + 1.0)*(P1**2.0 + P2**2.0)), 0],
        [-1.1*N*P2*np.exp(-(0.142857142857143*T - 3.57142857142857)**2)/(N + 0.5)**2 + 1.1*P2*np.exp(-(0.142857142857143*T - 3.57142857142857)**2)/(N + 0.5), 0.8*P1**1.0*P2**3.0*Z/((P1**2.0 + P2**2.0)**2*(P2 + 1.0)), 1.1*N*np.exp(-(0.142857142857143*T - 3.57142857142857)**2)/(N + 0.5) - 1.2*P2**2.0*Z/((P1**2.0 + P2**2.0)*(P2 + 1.0)) + 0.4*P2**3.0*Z/((P1**2.0 + P2**2.0)*(P2 + 1.0)**2) + 0.8*P2**4.0*Z/((P1**2.0 + P2**2.0)**2*(P2 + 1.0)) - 0.1, -0.4*P2**3.0/((P1**2.0 + P2**2.0)*(P2 + 1.0)), 0],
        [0, -0.48*P1**1.0*P2**3.0*Z/((P1**2.0 + P2**2.0)**2*(P2 + 1.0)) + 0.72*P1**2.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)) - 0.24*P1**3.0*Z/((P1 + 1.0)**2*(P1**2.0 + P2**2.0)) - 0.48*P1**4.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)**2), -0.48*P1**3.0*P2**1.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)**2) + 0.72*P2**2.0*Z/((P1**2.0 + P2**2.0)*(P2 + 1.0)) - 0.24*P2**3.0*Z/((P1**2.0 + P2**2.0)*(P2 + 1.0)**2) - 0.48*P2**4.0*Z/((P1**2.0 + P2**2.0)**2*(P2 + 1.0)), 0.24*P1**3.0/((P1 + 1.0)*(P1**2.0 + P2**2.0)) + 0.24*P2**3.0/((P1**2.0 + P2**2.0)*(P2 + 1.0)) - 0.15, 0],
        [0, -0.32*P1**1.0*P2**3.0*Z/((P1**2.0 + P2**2.0)**2*(P2 + 1.0)) + 0.48*P1**2.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)) - 0.16*P1**3.0*Z/((P1 + 1.0)**2*(P1**2.0 + P2**2.0)) - 0.32*P1**4.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)**2) + 0.1, -0.32*P1**3.0*P2**1.0*Z/((P1 + 1.0)*(P1**2.0 + P2**2.0)**2) + 0.48*P2**2.0*Z/((P1**2.0 + P2**2.0)*(P2 + 1.0)) - 0.16*P2**3.0*Z/((P1**2.0 + P2**2.0)*(P2 + 1.0)**2) - 0.32*P2**4.0*Z/((P1**2.0 + P2**2.0)**2*(P2 + 1.0)) + 0.1, 0.16*P1**3.0/((P1 + 1.0)*(P1**2.0 + P2**2.0)) + 0.16*P2**3.0/((P1**2.0 + P2**2.0)*(P2 + 1.0)) + 0.15, -0.05*2.0**((1/10)*T - 2.0) - 0.05]
    ], dtype=float)
